They are the _same_ thing, it's just converting:

```js
app.register(async (app) => {
  app.use((req, res, next) => next())

 app.get( ... )
})
```

to 

```js
app.route({
  method: 'GET',
  middlewares: [function (req, res, next) {
    next()
  }]
}, async (req, reply) => {})
```
